-- Season summaries for the Time Machine (record, coach, conference finish, postseason), by Time Machine season
-- (fall start year; the 2004 baseball season is stored as 2003). Shown at the top of each season with credit.
CREATE TABLE season_summaries (
  sport TEXT NOT NULL,
  season INTEGER NOT NULL,
  record TEXT,
  conf_record TEXT,
  conf_standing TEXT,
  conference TEXT,
  postseason TEXT,
  coach TEXT,
  source TEXT NOT NULL,
  source_url TEXT,
  PRIMARY KEY (sport, season)
);

